class Solution {
public:
    int triangleNumber(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = (int)nums.size();
        int ans = 0;
        for (int i = 0; i + 2 < n; i++) {
            int k = i + 2;
            for (int j = i + 1; j + 1 < n; j++) {
                if (k < j + 1) k = j + 1;
                while (k < n && nums[i] + nums[j] > nums[k]) k++;
                ans += k - j - 1;
            }
        }
        return ans;
    }
};
